ALTER TABLE villages ALTER COLUMN slug SET NOT NULL;

DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'uq_villages_slug') THEN
    ALTER TABLE villages ADD CONSTRAINT uq_villages_slug UNIQUE (slug);
  END IF;
END $$;
